-- Leads da Bruna (Setembro/2026) importados da planilha enviada.
-- Gerado automaticamente — 151 leads.

do $$
declare
  v_bruna_id bigint;
begin
  select id into v_bruna_id from equipe where nome = 'Bruna' limit 1;
  if v_bruna_id is null then
    raise exception 'Vendedora Bruna não encontrada na tabela equipe';
  end if;

end $$;

notify pgrst, 'reload schema';
